export function createLedger({ expectedAmounts = {} } = {}) {
  const records = new Map();
  const handledIds = new Set();

  const validTypes = new Set([
    "charge.success",
    "charge.failed",
    "charge.abandoned",
    "refund.processed",
  ]);

  const terminalChargeStatuses = new Set([
    "success",
    "partially_refunded",
    "refunded",
    "amount_mismatch",
  ]);

  function hasExpectedAmount(reference) {
    return Object.prototype.hasOwnProperty.call(expectedAmounts, reference);
  }

  function result(applied, reason, record) {
    return {
      applied,
      reason,
      status: record ? record.status : null,
    };
  }

  function applyRefund(record, amountKobo) {
    if (record.status === "refunded") return false;

    const total = record.refundedKobo + amountKobo;
    if (total > record.amountKobo) return false;

    record.refundedKobo = total;
    record.status =
      total === record.amountKobo ? "refunded" : "partially_refunded";
    return true;
  }

  function handle(event) {
    if (!event || !validTypes.has(event.type)) {
      return result(false, "unknown-type", null);
    }

    const { id, reference, type } = event;
    let record = records.get(reference);

    if (handledIds.has(id)) {
      return result(false, "duplicate", record);
    }

    const amountKobo = event.amountKobo;
    if (
      (type === "charge.success" || type === "refund.processed") &&
      (!Number.isInteger(amountKobo) || amountKobo <= 0)
    ) {
      return result(false, "invalid-amount", record);
    }

    handledIds.add(id);

    if (!record) {
      record = {
        reference,
        status: "pending",
        amountKobo: hasExpectedAmount(reference)
          ? expectedAmounts[reference]
          : null,
        refundedKobo: 0,
        deferredRefunds: [],
      };
      records.set(reference, record);
    }

    if (type === "refund.processed") {
      if (record.status === "amount_mismatch") {
        return result(false, "terminal", record);
      }

      if (
        record.status === "success" ||
        record.status === "partially_refunded" ||
        record.status === "refunded"
      ) {
        const applied = applyRefund(record, amountKobo);
        return result(applied, applied ? null : "over-refund", record);
      }

      record.deferredRefunds.push(amountKobo);
      return result(false, "deferred", record);
    }

    if (terminalChargeStatuses.has(record.status)) {
      return result(false, "terminal", record);
    }

    if (type === "charge.failed") {
      if (record.status === "failed") {
        return result(false, "stale", record);
      }

      record.status = "failed";
      return result(true, null, record);
    }

    if (type === "charge.abandoned") {
      if (record.status !== "pending") {
        return result(false, "stale", record);
      }

      record.status = "abandoned";
      return result(true, null, record);
    }

    // The remaining event type is charge.success.
    const expectedKnown = hasExpectedAmount(reference);
    const expectedAmount = expectedKnown ? expectedAmounts[reference] : null;

    if (expectedKnown && amountKobo !== expectedAmount) {
      record.status = "amount_mismatch";
      record.deferredRefunds.length = 0;
      return result(true, "amount-mismatch", record);
    }

    record.amountKobo = expectedKnown ? expectedAmount : amountKobo;
    record.status = "success";

    // Replay in arrival order, silently dropping any over-refunds.
    for (const refundAmount of record.deferredRefunds) {
      applyRefund(record, refundAmount);
    }
    record.deferredRefunds.length = 0;

    return result(true, null, record);
  }

  function get(reference) {
    const record = records.get(reference);
    if (!record) return undefined;

    return {
      reference: record.reference,
      status: record.status,
      amountKobo: record.amountKobo,
      refundedKobo: record.refundedKobo,
    };
  }

  return { handle, get };
}
